-- ---------------------------------------------------------------------------
-- Conteúdo do Explorar (Fase 1c): um post de foto já publicado, com métricas
-- de leitura, para a listagem e a edição em /conteudo terem o que mostrar.
-- Os caminhos seguem o contrato do bucket ({tenant}/{store}/{uuid}.jpg), mas
-- a mídia aponta para uma foto pública — o objeto não existe no Storage local
-- (o card de órfãos ignora: só lista o que ESTÁ no bucket sem registro).
-- ---------------------------------------------------------------------------
  id, store_id, tenant_id, product_id, tipo, media_path, media_url, thumb_path, thumb_url,
  descricao, tags, status, moderacao, largura, altura, bytes, curtidas, comentarios, views, publicado_em
) VALUES (
  '20000000-0000-4000-8000-000000000001',
  'f0000000-0000-4000-8000-000000000001',
  'd0000000-0000-4000-8000-000000000001',
  '10000000-0000-4000-8000-000000000001',
  'foto',
  'd0000000-0000-4000-8000-000000000001/f0000000-0000-4000-8000-000000000001/20000000-0000-4000-8000-000000000001.jpg',
  'https://picsum.photos/seed/forno-post-1/900/1400',
  'd0000000-0000-4000-8000-000000000001/f0000000-0000-4000-8000-000000000001/20000000-0000-4000-8000-000000000001-thumb.jpg',
  'https://picsum.photos/seed/forno-post-1/450/700',
  'Margherita saindo do forno a lenha — massa de 48 horas.',
